Rules.InvariantScript:
SortByColumns(
    Filter(
        tbl_FOD,

        // ✅ Aeroporto — opcional
        IsBlank(ComboboxCanvasAeroporto.Selected.Value) ||
        aeroporto = ComboboxCanvasAeroporto.Selected.Value,

        // ✅ Data Início — opcional
        IsBlank(dtpHomeDtfInicio.SelectedDate) ||
        data >= DateTimeValue(dtpHomeDtfInicio.SelectedDate),

        // ✅ Data Término — opcional
        IsBlank(dtpHomeDtfTermino.SelectedDate) ||
        data < DateAdd(
            DateTimeValue(dtpHomeDtfTermino.SelectedDate),
            1,
            TimeUnit.Days
        ),

        // ✅ Busca por Identificação — opcional
        IsBlank(SearchInput1.Value) ||
        StartsWith(identificacao, SearchInput1.Value)
    ),
    "ID",
    SortOrder.Descending
)

UpdateContext(
    {
        isItemSelected: true,
        newMode: false,
        editMode: false,
        CurrentItem: ThisItem,
        var_selectTipoFOD: ThisItem.tipo
    }
)

Remove(
    tbl_FOD,
    selectedRecord
);
If(
    IsEmpty(
        Errors(
            tbl_FOD,
            selectedRecord
        )
    ),
    Navigate(
        ScreenSucesso,
        ScreenTransition.Fade,
        {var_navigateSucess: ScreenFOD}
    );
    UpdateContext(
        {
            isItemSelected: false,
            newMode: false,
            deleteMode: false
        }
    )
);

